import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"跨平台架构","description":"","frontmatter":{"title":"跨平台架构"},"headers":[],"relativePath":"zh/guide/platforms.md","filePath":"zh/guide/platforms.md","lastUpdated":0}`),a={name:`zh/guide/platforms.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="_11-跨平台架构" tabindex="-1">11. 跨平台架构 <a class="header-anchor" href="#_11-跨平台架构" aria-label="Permalink to “11. 跨平台架构”">​</a></h1><h2 id="_11-1-统一平台接口" tabindex="-1">11.1 统一平台接口 <a class="header-anchor" href="#_11-1-统一平台接口" aria-label="Permalink to “11.1 统一平台接口”">​</a></h2><p>建议抽象：</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ProcessController</span></span>
<span class="line"><span>ServiceController</span></span>
<span class="line"><span>NetworkInterfaceController</span></span>
<span class="line"><span>NetworkConnectivityProbe</span></span>
<span class="line"><span>CredentialProvider</span></span>
<span class="line"><span>SystemRebootController</span></span></code></pre></div><p>每个接口只定义跨平台共同语义。平台专属能力通过 Capability 描述，不得为了统一接口而伪造平台支持。</p><h2 id="_11-2-windows" tabindex="-1">11.2 Windows <a class="header-anchor" href="#_11-2-windows" aria-label="Permalink to “11.2 Windows”">​</a></h2><p>需要支持的能力逐步包括：</p><ul><li>进程检测。</li><li>Windows Service 控制。</li><li>Wi-Fi 状态检测。</li><li>Wi-Fi 重连。</li><li>网络接口重置。</li><li>DNS 刷新。</li><li>IP 配置检查。</li><li>默认网关检查。</li><li>网络连通性检查。</li><li>向日葵进程或服务检查。</li><li>有授权的系统重启。</li></ul><p>Wi-Fi 重连涉及凭据、网卡和系统权限，应使用系统支持的 API 或受控命令。</p><p>如果重置网卡可能导致管理连接中断，必须在策略中明确标记风险。</p><h2 id="_11-3-linux" tabindex="-1">11.3 Linux <a class="header-anchor" href="#_11-3-linux" aria-label="Permalink to “11.3 Linux”">​</a></h2><p>需要支持：</p><ul><li>进程检测。</li><li>systemd 服务控制。</li><li>OpenRC 后续适配。</li><li>网络接口状态。</li><li>IP 和路由检查。</li><li>DNS 检查。</li><li>受控命令执行。</li><li>系统重启。</li></ul><p>不能假设所有 Linux 系统都使用 systemd。</p><h2 id="_11-4-macos" tabindex="-1">11.4 macOS <a class="header-anchor" href="#_11-4-macos" aria-label="Permalink to “11.4 macOS”">​</a></h2><p>后续支持：</p><ul><li>进程检测。</li><li>launchd 服务管理。</li><li>网络接口状态。</li><li>Wi-Fi 重连。</li><li>网络连通性检查。</li><li>系统重启。</li></ul><h2 id="_11-5-bsd" tabindex="-1">11.5 BSD <a class="header-anchor" href="#_11-5-bsd" aria-label="Permalink to “11.5 BSD”">​</a></h2><p>后续支持：</p><ul><li>进程检测。</li><li>rc.d 服务管理。</li><li>网络接口与路由状态。</li><li>系统重启。</li></ul><h2 id="_11-6-openwrt" tabindex="-1">11.6 OpenWrt <a class="header-anchor" href="#_11-6-openwrt" aria-label="Permalink to “11.6 OpenWrt”">​</a></h2><p>后续支持：</p><ul><li>procd 服务管理。</li><li>UCI 配置读取和受控修改。</li><li>ubus 调用。</li><li>网络接口和路由检查。</li><li>OpenClash 状态检测。</li><li>代理节点切换。</li><li>服务重启。</li></ul><p>所有网络和防火墙变更必须有明确作用范围、前置条件、风险等级和验证步骤。</p><p>禁止默认清空防火墙规则、重置所有路由或无条件覆盖现有网络配置。</p><hr>`,26)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};